#!/usr/bin/env python3
"""Emit idna_tables.go: the data behind CPython's `str.encode('idna')`.

    ~/cf-test/.venv/bin/python server/internal/rules/testdata/gen_idna.py > server/internal/rules/idna_tables.go

Contents (all derived from CPython 3.11's own stringprep/unicodedata, Unicode 14):
nameprep tables B.1/B.2, the union of the prohibited tables C.1.2-C.9, D.1/D.2
(bidi), plus what NFKC needs (NFKD decompositions, combining classes,
canonical composition pairs).
"""
import stringprep
import sys
import unicodedata

assert sys.version_info[:2] == (3, 11), sys.version
CPS = [c for c in range(0x110000) if not 0xD800 <= c <= 0xDFFF]


def ranges(pred):
    out, start, prev = [], None, None
    for c in CPS:
        if pred(chr(c)):
            if start is None:
                start = c
            prev = c
        elif start is not None:
            out.append((start, prev))
            start = None
    if start is not None:
        out.append((start, prev))
    return out


def lit(text):
    return '"' + ''.join('\\U%08x' % ord(ch) for ch in text) + '"'


def emit_ranges(name, items):
    print(f'var {name} = []runeRange{{')
    for i in range(0, len(items), 6):
        print('\t' + ' '.join('{0x%x, 0x%x},' % pair for pair in items[i:i + 6]))
    print('}\n')


prohibited = (stringprep.in_table_c12, stringprep.in_table_c22, stringprep.in_table_c3, stringprep.in_table_c4,
              stringprep.in_table_c5, stringprep.in_table_c6, stringprep.in_table_c7, stringprep.in_table_c8,
              stringprep.in_table_c9)
print('// Code generated by testdata/gen_idna.py from CPython 3.11; DO NOT EDIT.\n\npackage rules\n')
print('type runeRange struct{ lo, hi rune }\ntype runeMapping struct {\n\tcp   rune\n\ttext string\n}\n')
print('type combiningClass struct {\n\tlo, hi rune\n\tclass  uint8\n}\ntype compositionPair struct{ first, second, result rune }\n')
emit_ranges('idnaTableB1', ranges(stringprep.in_table_b1))
emit_ranges('idnaTableProhibited', ranges(lambda ch: any(table(ch) for table in prohibited)))
emit_ranges('idnaTableD1', ranges(stringprep.in_table_d1))
emit_ranges('idnaTableD2', ranges(stringprep.in_table_d2))
print('var idnaMapB2 = []runeMapping{')
for c in CPS:
    mapped = stringprep.map_table_b2(chr(c))
    if mapped != chr(c):
        print('\t{0x%x, %s},' % (c, lit(mapped)))
print('}\n')
print('var nfkdMappings = []runeMapping{')
for c in CPS:
    if 0xAC00 <= c <= 0xD7A3:  # Hangul syllables decompose algorithmically
        continue
    mapped = unicodedata.normalize('NFKD', chr(c))
    if mapped != chr(c):
        print('\t{0x%x, %s},' % (c, lit(mapped)))
print('}\n')
print('var combiningClasses = []combiningClass{')
start = prev = klass = None
for c in CPS + [None]:
    value = unicodedata.combining(chr(c)) if c is not None else 0
    if start is not None and (value != klass or c is None or c != prev + 1):
        print('\t{0x%x, 0x%x, %d},' % (start, prev, klass))
        start = None
    if c is not None and value and start is None:
        start, klass = c, value
    prev = c
print('}\n')
print('var compositionPairs = []compositionPair{')
for c in CPS:
    decomposition = unicodedata.decomposition(chr(c))
    if not decomposition or decomposition.startswith('<'):
        continue
    parts = [int(part, 16) for part in decomposition.split()]
    if 0xAC00 <= c <= 0xD7A3:
        continue
    if len(parts) == 2 and unicodedata.normalize('NFC', chr(parts[0]) + chr(parts[1])) == chr(c):
        print('\t{0x%x, 0x%x, 0x%x},' % (parts[0], parts[1], c))
print('}')
